import AVFoundation
import AppKit
import CoreVideo
import Metal
import MetalPerformanceShaders

/// One `AVVideoComposition` instruction, carrying the `RecipeSource` slot the
/// frames inside it must be read from (spec §7.5).
///
/// The key is why this type exists instead of `AVVideoCompositionInstruction`:
/// `AVFoundation` instantiates ONE compositor object per player item and hands
/// it nothing about the document, so with a process-wide "current project" two
/// open windows would render each other's frames. The key travels on the
/// instruction, which the request hands back, so a document can only ever read
/// its own recipe. `mediaURLs` rides along for the same reason — an `image`
/// layer names a media id and only the document knows the file.
final class RecipeInstruction: NSObject, AVVideoCompositionInstructionProtocol {
    let timeRange: CMTimeRange
    let enablePostProcessing: Bool = false
    /// True: a transition changes every frame inside its instruction, so
    /// AVFoundation must not reuse one composed frame across the range.
    let containsTweening: Bool = true
    // `nonisolated(unsafe)`: the protocol is `Sendable` and `NSValue` is not,
    // but this array is built once in `init` and never mutated, which is the
    // exact case the attribute exists for.
    nonisolated(unsafe) let requiredSourceTrackIDs: [NSValue]?
    /// Never a passthrough: every frame goes through the Metal pipeline, even
    /// a single full-frame layer, so opacity and colour edits show without a
    /// composition rebuild (§7.6).
    let passthroughTrackID: CMPersistentTrackID = kCMPersistentTrackID_Invalid

    /// The document's `RecipeSource` slot (`RecipeSource.swift`) — or an
    /// export's own, which is a fresh one. It names the project a frame is
    /// composed from AND, since phase 7, the `RecipeOptions` that project is
    /// asked with, so an option never has to be threaded through the
    /// instruction.
    let recipeKey: Int
    /// Media id → file, for `image` layers. Same map `CompositionBuilder`
    /// resolved the composition's assets from.
    let mediaURLs: [UInt32: URL]
    /// Composition video track id → the source orientation code
    /// (`CompositionBuilder.orientationCode`) of whatever that track is
    /// showing across THIS instruction. Per instruction because an
    /// instruction boundary falls wherever the visible clips change (§7.2),
    /// so within one, a track shows exactly one clip.
    let sourceOrientations: [Int: Int]
    /// Clips whose media file is gone (spec §5.6). A `track` layer with no
    /// source frame is normally just a gap, so the compositor cannot tell the
    /// two apart on its own — the plan can, because it knows which media each
    /// clip's segment came from and `urls` says which of those resolved.
    /// These get the slate instead of nothing.
    let missingClips: Set<UInt32>
    /// Composition video track ids whose segment across THIS instruction is a
    /// full-range media (spec §11 GR-22): a log curve's code domain follows
    /// it. Per instruction for `sourceOrientations`' reason; empty when no
    /// segment converts with a log curve.
    let fullRangeTracks: Set<Int>

    init(
        timeRange: CMTimeRange, requiredTrackIDs: [Int], recipeKey: Int,
        mediaURLs: [UInt32: URL], sourceOrientations: [Int: Int],
        missingClips: Set<UInt32>, fullRangeTracks: Set<Int> = []
    ) {
        self.timeRange = timeRange
        self.requiredSourceTrackIDs = requiredTrackIDs.map {
            NSNumber(value: CMPersistentTrackID($0))
        }
        self.recipeKey = recipeKey
        self.mediaURLs = mediaURLs
        self.sourceOrientations = sourceOrientations
        self.missingClips = missingClips
        self.fullRangeTracks = fullRangeTracks
        super.init()
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("RecipeInstruction does not support NSCoder")
    }
}

/// Why a frame could not be composed. Every one is reported through
/// `request.finish(with:)` — AVFoundation then drops that frame and keeps
/// playing, which is the whole point: a compositor that throws or traps takes
/// the player down with it.
enum CompositorError: LocalizedError {
    case metalUnavailable
    case noPixelBuffer
    case noDestinationTexture

    var errorDescription: String? {
        switch self {
        case .metalUnavailable: return "Metal is not available on this system."
        case .noPixelBuffer: return "The render context ran out of pixel buffers."
        case .noDestinationTexture: return "The frame buffer could not be used as a texture."
        }
    }
}

/// The custom compositor (spec §7.5): one Metal pipeline, one pass per layer,
/// back to front, source-over into the destination.
///
/// AVFoundation creates this object itself (`customVideoCompositorClass`), so
/// it can take no arguments — everything per-document arrives on the
/// instruction. Requests are served on one serial queue and every exit path
/// answers the request exactly once.
class Compositor: NSObject, AVVideoCompositing {

    /// `defaults write com.kgalligan.FrameJob FrameJobCompositorTiming -bool YES`
    /// turns on the per-frame timing log — the measurement M1 step 5 is
    /// verified with ("playback stays at 60 fps on a 1080p source").
    static let timingDefaultsKey = "FrameJobCompositorTiming"

    private static let timingEnabled = UserDefaults.standard.bool(forKey: timingDefaultsKey)

    /// The one documented GCD seam on this side (app/CLAUDE.md): AVFoundation
    /// calls `startRequest` from its own threads and expects the work to be
    /// asynchronous, and a serial queue is what keeps GPU submission ordered.
    private let renderQueue = DispatchQueue(
        label: "com.kgalligan.framejob.compositor", qos: .userInitiated)

    private let renderer: MetalRenderer?
    private let lock = NSLock()
    private var renderContext: AVVideoCompositionRenderContext?
    private var cancelled = false
    private var frames = 0
    private var totalSeconds = 0.0
    private var worstSeconds = 0.0

    override init() {
        renderer = MetalRenderer()
        super.init()
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("Compositor does not support NSCoder")
    }

    // MARK: - AVVideoCompositing

    /// The render context's buffers: 16-bit float, so a blend or a deep
    /// source keeps more than 256 levels a channel (spec §11 PR-1). The
    /// working format of every target a layer pipeline draws into follows it
    /// (`MetalRenderer.workingFormat`), and the export reader reads it.
    static let outputPixelFormat: OSType = REDACTED
    /// What every video source is decoded to: 16-bit float, so a 10-bit source
    /// keeps its levels; the layer stage clamps its values (spec §11 PR-2).
    static let sourcePixelFormat: OSType = REDACTED

    /// Metal-compatible `sourcePixelFormat`, sampled through `texture(from:)`.
    /// AVFoundation converts any other pixel format; for a
    /// `ConvertingCompositor` not colour: an HDR or wide-gamut frame arrives
    /// native and labelled, and step 0 converts it (spec §11 GR-15, §7.5).
    var sourcePixelBufferAttributes: [String: any Sendable]? {
        [
            kCVPixelBufferPixelFormatTypeKey as String: Int(Compositor.sourcePixelFormat),
            kCVPixelBufferMetalCompatibilityKey as String: true,
        ]
    }

    /// Today's answers, stated: AVFoundation conforms every source to the
    /// composition's colour, so an SDR-only project keeps its pixels and
    /// labels. A composition holding an HLG, PQ or wide-gamut source is built
    /// with `ConvertingCompositor` instead (`Compositor+Input.swift`, spec
    /// §11 GR-15 as amended), which answers both true and runs step 0.
    var canConformColorOfSourceFrames: Bool { false }
    /// False here; true in `ConvertingCompositor` (see above).
    var supportsHDRSourceFrames: Bool { false }

    var requiredPixelBufferAttributesForRenderContext: [String: any Sendable] {
        [
            kCVPixelBufferPixelFormatTypeKey as String: Int(Compositor.outputPixelFormat),
            kCVPixelBufferMetalCompatibilityKey as String: true,
        ]
    }

    /// A new context means new pixel buffers, so every `CVMetalTexture`
    /// wrapping a buffer from the OLD context is stale — the cache is flushed
    /// rather than left to age out, because those textures pin IOSurfaces the
    /// old context is trying to release.
    func renderContextChanged(_ newRenderContext: AVVideoCompositionRenderContext) {
        lock.lock()
        renderContext = newRenderContext
        lock.unlock()
        renderer?.flushPixelBufferTextures()
    }

    func startRequest(_ asyncVideoCompositionRequest: AVAsynchronousVideoCompositionRequest) {
        renderQueue.async { [weak self] in
            guard let self = self else {
                asyncVideoCompositionRequest.finishCancelledRequest()
                return
            }
            guard !self.isCancelled else {
                asyncVideoCompositionRequest.finishCancelledRequest()
                return
            }
            self.serve(asyncVideoCompositionRequest)
        }
    }

    /// Flushes the queue: the cancelled flag makes every request already
    /// queued answer `finishCancelledRequest`, and the empty `sync` waits for
    /// the one in flight. AVFoundation calls this on a seek and at teardown,
    /// and requires that no request be left unanswered.
    func cancelAllPendingVideoCompositionRequests() {
        setCancelled(true)
        renderQueue.sync {}
        setCancelled(false)
    }

    // MARK: - Serving one frame

    private func serve(_ request: AVAsynchronousVideoCompositionRequest) {
        let started = CFAbsoluteTimeGetCurrent()
        guard let renderer = renderer else {
            request.finish(with: CompositorError.metalUnavailable)
            return
        }
        guard let destination = request.renderContext.newPixelBuffer() else {
            request.finish(with: CompositorError.noPixelBuffer)
            return
        }
        let instruction = request.videoCompositionInstruction as? RecipeInstruction
        let key = instruction?.recipeKey ?? 0
        let ticks = CompositionBuilder.ticks(request.compositionTime)
        // A playing preview's prefetch follows the frame asked for (G-36 (d)).
        GraphicPrefetch.shared.reach(key, ticks: ticks)
        // The key is the whole ask: `RecipeSource.recipe(for:at:)` reads the
        // project AND that key's `RecipeOptions` under one hold, so a burn-in
        // an export asked for arrives here without this file, the
        // instruction or `CompositionBuilder` carrying a flag of its own
        // (spec §7.3). Do not read the two halves separately.
        let recipe = RecipeSource.shared.recipe(for: key, at: ticks)
        do {
            try renderer.render(
                recipe: recipe, into: destination, request: request, instruction: instruction,
                converts: canConformColorOfSourceFrames)
            request.finish(withComposedVideoFrame: destination)
            #if FRAMEJOB_DEV_TOOLS
            PlaybackTrials.shared.served(
                key, ticks: ticks, seconds: CFAbsoluteTimeGetCurrent() - started,
                buffer: destination)
            #endif
            WaveformTaps.shared.offer(
                destination, key: instruction?.recipeKey ?? 0,
                signal: ScopeSignal(canvas: recipe?.canvas))
        } catch {
            // A frame that will not compose is dropped: the player shows the last one.
            request.finish(with: error)
        }
        record(CFAbsoluteTimeGetCurrent() - started)
    }

    // MARK: - Timing log

    /// Averages over a two-second window (120 frames) and reports the worst
    /// frame in it, which is the number that matters — an 8 ms budget with a
    /// 40 ms outlier every second still stutters (§7.5).
    private func record(_ seconds: Double) {
        guard Compositor.timingEnabled else { return }
        lock.lock()
        frames += 1
        totalSeconds += seconds
        worstSeconds = max(worstSeconds, seconds)
        let due = frames >= 120
        let average = totalSeconds / Double(max(frames, 1)) * 1000
        let worst = worstSeconds * 1000
        if due {
            frames = 0
            totalSeconds = 0
            worstSeconds = 0
        }
        lock.unlock()
        if due {
            // Step 0's passes over the same window (spec §11 GR-15): 0 for a
            // frame with no converted source. Appended, so the line's prefix
            // stays what the proofs' timing pattern reads.
            let passes = renderer?.inputs.takePassCount() ?? 0
            NSLog("[framejob] compositor: %.2f ms average, %.2f ms worst over 120 frames, "
                + "%ld input passes", average, worst, passes)
        }
    }

    private var isCancelled: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancelled
    }

    private func setCancelled(_ value: Bool) {
        lock.lock()
        cancelled = value
        lock.unlock()
    }
}

import AppKit

/// The sheet that stays up for the write itself: a bar, a Cancel that really
/// stops the session, and — once the file lands — the result and a Show in
/// Finder (spec §10 step 10).
///
/// It owns the `Exporter`, which is why the export survives everything the
/// editor does next: the sheet is retained by the presenting controller for
/// as long as it is on screen, and nothing else holds the session.
///
/// Its own file rather than the foot of `ExportSheetController.swift`, which
/// stood at 1114 lines against app/CLAUDE.md's ~600 cap. The seam is where
/// the two sheets stop having anything in common: the settings card is a
/// conversation with the core — every number it shows comes back from
/// `rc_export_settings`, and its controls only decide what to ask for — and
/// this one has already finished asking. It holds a project handle, a URL and
/// an `Exporter`, watches one number climb, and turns into its own result
/// panel; nothing on it can change what is being written.
///
/// Being a separate CLASS is what makes the cut free. `private` on an
/// extension member reaches only its own file, so splitting a type across
/// files costs every crossing member its privacy — the price
/// `ExporterLoudness.swift` records paying, and the price the two `extension
/// ExportSheetController` files beside this one pay. A type carries its own
/// scope, so every member below keeps the visibility it had, and
/// `EditorViewController+Export.swift` presenting it is the only name that
/// crosses.
final class ExportProgressSheetController: NSViewController {
    private let exporter = Exporter()
    /// The project handle as the export was confirmed. Handles are immutable
    /// (spec §5.5), so edits made after this point cannot reach the file.
    private let project: ReelProject
    private let urls: [UInt32: URL]
    private let settings: ExportSettings
    private let destination: URL
    /// What the export asks of the RECIPE rather than of the settings — the
    /// timecode burn-in (spec §7.3, road map 2's phase 7). It is a separate
    /// argument because it is a separate question: `ExportSettings` is what
    /// `rc_export_settings` resolved, and an option posted through the
    /// override table would be dropped in silence and the file reported a
    /// success. Defaulted, so a caller that does not burn in is written the
    /// way it always was.
    private let options: RecipeOptions
    /// The document's compiled graphics as the export was confirmed (G-13),
    /// pinned by `Exporter.export` for the write.
    private let graphics: GraphicSet?

    private let bar = NSProgressIndicator()
    private let statusLabel = NSTextField(wrappingLabelWithString: "Preparing…")
    private let percentLabel = NSTextField(labelWithString: "0 %")
    /// Set in `loadView`; the only implicitly-unwrapped optionals the file has
    /// (app/CLAUDE.md allows them for exactly this).
    private var stopButton: NSButton!
    private var revealButton: NSButton!

    private var didStart = false
    private var didFinish = false
    /// This export's booking in the encoder ledger (spec §11 CX-18): counted, never held —
    /// a person who chose Export… asked to write now. nil on an AVFoundation row and once
    /// it is over.
    private var ledgerToken: UInt64?

    init(
        project: ReelProject, urls: [UInt32: URL], settings: ExportSettings, to url: URL,
        options: RecipeOptions = .none, graphics: GraphicSet? = nil
    ) {
        self.project = project
        self.urls = urls
        self.settings = settings
        self.destination = url
        self.options = options
        self.graphics = graphics
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ExportProgressSheetController does not support NSCoder")
    }

    deinit {
        let token = ledgerToken
        ledgerToken = nil
        ExportEncoderLedger.shared.end(token)
    }

    override func loadView() {
        styleSheetProgressBar(bar)

        styleSheetStatusLabel(statusLabel)
        statusLabel.stringValue = "Preparing “\(destination.lastPathComponent)”…"

        percentLabel.font = DS.mono(11)
        percentLabel.textColor = DS.textFaint

        let content = makeProgressStack([bar, statusLabel, percentLabel])

        stopButton = StickerButton(
            title: "Cancel", style: .secondary, target: self, action: #selector(stopClicked(_:)))
        revealButton = StickerButton(
            title: "Show in Finder", style: .primary, target: self,
            action: #selector(revealClicked(_:)))
        hideReturnTarget(revealButton)

        view = makeSheetView(
            title: "Exporting",
            content: content,
            buttonRow: makeButtonRow(cancel: stopButton, apply: revealButton))
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard !didStart else { return }
        didStart = true
        // Booked BEFORE `export`, whose early refusals finish synchronously inside it.
        ledgerToken = ExportEncoderLedger.shared.begin(settings)
        exporter.export(
            project: project, urls: urls, settings: settings, to: destination, options: options,
            graphics: graphics,
            progress: { [weak self] value in self?.progressed(value) },
            completion: { [weak self] result in self?.finished(result) })
    }

    // MARK: - Exporter callbacks

    private func progressed(_ value: Double) {
        guard !didFinish else { return }
        let clamped = min(max(value, 0), 1)
        bar.doubleValue = clamped
        percentLabel.stringValue = "\(Int((clamped * 100).rounded())) %"
        // The exporter names its own phase while it has one. Without this the
        // label would claim to be writing a file during the loudness
        // measurement — which on an audio-only export is half the wait, and
        // the half where nothing is on disk yet.
        if let phase = exporter.phaseDescription {
            statusLabel.stringValue = phase
        } else if clamped > 0 {
            statusLabel.stringValue = "Writing “\(destination.lastPathComponent)”…"
        }
    }

    /// The one exit for all three outcomes. Cancelling closes the sheet and
    /// removes the half-written file; success and failure both turn the sheet
    /// into its own result panel rather than trading it for an alert.
    private func finished(_ result: Result<URL, any Error>) {
        didFinish = true
        // Cleared before `end`, whose post may launch a held queue job.
        let token = ledgerToken
        ledgerToken = nil
        ExportEncoderLedger.shared.end(token)
        stopButton.isEnabled = true
        switch result {
        case .success(let url):
            bar.doubleValue = 1
            percentLabel.stringValue = "100 %"
            // What the file actually holds, normalised or not: the export
            // measured its own mix on the way through, so the numbers are a
            // report rather than a promise.
            let measured = exporter.loudnessReport.map { " \($0.summary)." } ?? ""
            // What the graphics warned while the file was drawn: a count on
            // the line, the list in its tooltip (G-24 (c)).
            let warnings = exporter.graphicWarnings
            statusLabel.stringValue = "Exported “\(url.lastPathComponent)”.\(measured)"
                + Exporter.graphicWarningSuffix(warnings)
            statusLabel.toolTip = Exporter.graphicWarningDetails(warnings)
            statusLabel.textColor = DS.textStrong
            stopButton.title = "Close"
            revealButton.isHidden = false
            revealButton.isEnabled = true
        case .failure(let error):
            if case Exporter.ExportError.cancelled = error {
                try? FileManager.default.removeItem(at: destination)
                dismiss(self)
                return
            }
            bar.doubleValue = 0
            percentLabel.stringValue = ""
            statusLabel.stringValue = error.localizedDescription
            statusLabel.textColor = DS.textStrong
            stopButton.title = "Close"
        }
    }

    // MARK: - Buttons

    /// Cancel while it runs, Close once it is over. One button because there
    /// is only ever one thing to do with a sheet that is busy.
    @objc private func stopClicked(_ sender: Any?) {
        guard !didFinish else {
            dismiss(self)
            return
        }
        stopButton.isEnabled = false
        statusLabel.stringValue = "Stopping…"
        exporter.cancel()
    }

    @objc private func revealClicked(_ sender: Any?) {
        guard didFinish else { return }
        NSWorkspace.shared.activateFileViewerSelecting([destination])
        dismiss(self)
    }
}

import Foundation

// MARK: - The dev-tools seam: tools compiled only under FRAMEJOB_DEV_TOOLS

/// Where the dev tools live (road map 11, spec §11 V-1 and V-2).
///
/// **The flag.** `FRAMEJOB_DEV_TOOLS` is a Swift compilation condition that
/// Debug and Release set and the Distribution configuration does not
/// (`project.yml`), so every proof and agent session, which launch Release,
/// has the dev tools and the binary `make dist` builds has none of their
/// code (V-1). A dev tool is an ORDINARY tool (V-2): a handler in
/// `devHandlers`, a row from `devTools()`, and nothing else — the parity
/// check, the argument gate and the schema checks cover it as they cover a
/// product tool, in both builds, because both tables are merged before any
/// of them reads.
///
/// **Why the check greps a marker, not tool names.** Swift string literals
/// of 15 UTF-8 bytes or fewer are stored inline in the code of an `-O`
/// binary, not as contiguous bytes, so a short tool name such as
/// `snapshot_ui` (11) can never be found in either build and an absence
/// check on it would pass for nothing. `tools/proof/dist_check.py` reads
/// `devToolsMarker` out of this file instead — at least 16 bytes — and
/// requires it present in Release's binary and absent from Distribution's.
///
/// **What keeps the marker live.** The flag-on `devTools()` logs it, so the
/// optimiser cannot drop the literal. V2 adds rows and handlers here with no
/// edit to the check.
///
/// **Where the rows go.** `catalogJSON()` splices `devTools()` in
/// immediately BEFORE the file tools, never at the end: the catalog's last
/// eleven names are the file group plus `record_screen`, which
/// `recording_probe.py` asserts. Swift takes no `#if` inside a dictionary
/// literal, so `AgentServer.swift` merges `devHandlers` through
/// `withDevHandlers` and `devOffMainTools` by a union, one line each.
extension AgentServer {
    typealias ToolHandler = (AgentServer) -> ([String: Any]) throws -> String

    /// `product` with `devHandlers` merged in. A dev tool that reuses a
    /// product tool's name keeps the PRODUCT handler and complains the way
    /// the startup parity check does.
    static func withDevHandlers(_ product: [String: ToolHandler]) -> [String: ToolHandler] {
        var merged = product
        for (name, handler) in devHandlers.sorted(by: { $0.key < $1.key }) {
            if merged[name] != nil {
                let msg = "dev tool \(name) reuses a product tool's name"
                assertionFailure(msg)
                NSLog("Frame Job: %@", msg)
                continue
            }
            merged[name] = handler
        }
        return merged
    }

    /// Every dev tool's name, in either build (empty in Distribution): the
    /// assistant withholds each one (spec §11 AI-7, `AssistantToolTable`).
    static var devToolNames: Set<String> { Set(devHandlers.keys) }

    #if FRAMEJOB_DEV_TOOLS
    // dist_check.py parses the next line (D1) and requires it bare — nothing after the
    // closing quote — at least 16 bytes, present in Release's binary, absent from Distribution's.
    static let devToolsMarker = "framejob-dev-tools-compiled-in"

    private static let devHandlers: [String: ToolHandler] = [
        // AgentServer+Snapshot.swift
        "snapshot_ui": { $0.snapshotUI },
        // AgentServer+MenuItem.swift
        "perform_menu_item": { $0.performMenuItem },
        "cancel_sheet": { $0.cancelSheet },
        // AgentServer+InspectorTab.swift
        "select_inspector_tab": { $0.selectInspectorTab },
        // AgentServer+Assistant.swift
        "assistant_send": { $0.assistantSend },
        "assistant_answer": { $0.assistantAnswer },
        // AgentServer+PlayPreview.swift
        "play_preview": { $0.playPreview },
        // AgentServer+GraphicMemory.swift
        "graphic_memory": { $0.graphicMemory },
    ]

    static let devOffMainTools: Set<String> = [
        "snapshot_ui", "perform_menu_item", "cancel_sheet", "assistant_send", "assistant_answer",
        "play_preview", "graphic_memory",
    ]

    /// The dev tools' catalog rows, in catalog order: `snapshot_ui` (V2a),
    /// `perform_menu_item` and `cancel_sheet` (V2b), `select_inspector_tab`
    /// (V3), `assistant_send` and `assistant_answer` (road map 12 A1),
    /// `play_preview` (issue #127, G-36), `graphic_memory` (issue #127,
    /// G-37). The log is what keeps `devToolsMarker` in the optimised binary;
    /// it never says `Frame Job: `, the prefix a proof reads as the parity
    /// check complaining.
    func devTools() -> [[String: Any]] {
        let rows: [[String: Any]] = [
            snapshotUITool(), performMenuItemTool(), cancelSheetTool(), selectInspectorTabTool(),
            assistantSendTool(), assistantAnswerTool(), playPreviewTool(), graphicMemoryTool(),
        ]
        NSLog("Frame Job agent server: %@, %ld dev tools", Self.devToolsMarker, rows.count)
        return rows
    }
    #else
    private static let devHandlers: [String: ToolHandler] = [:]

    static let devOffMainTools: Set<String> = []

    /// Distribution ships no dev tools.
    func devTools() -> [[String: Any]] {
        []
    }
    #endif
}

import Foundation

/// The export queue (road map 2's phase 7e): the exports a person has
/// confirmed but does not want to sit and watch, run one after another while
/// the editor stays live.
///
/// **There is no AppKit in this file, and that is the design rather than
/// tidiness.** A queue window can be checked by neither of this project's two
/// instruments: the offscreen harness renders an `EditorViewController` into a
/// window and nothing else, and MCP drives the app through tools — and the
/// agent's `export` enqueues here, so a tool reaches this list but never the
/// window (below, spec §11 #326). What a proof CAN do is
/// compile a probe out of the whole of `app/Sources`
/// (`tools/proof/phase6_chrome.py`'s `build_probe`), make one of these,
/// enqueue two jobs, spin the main run loop until `isIdle` and read `jobs`
/// back — without an `NSWindow` ever being ordered front. So the job list and
/// its state machine live here, where a script can reach them, and
/// `ExportQueueWindowController.swift` is a READER of this and nothing else:
/// it holds no job, decides nothing, and closing it stops nothing.
/// `AudioNormalize.swift` and `CaptionLayout.swift` are the same split — the
/// arithmetic where a script can call it, the dialog around it — and phase 5's
/// level meter is the closest sibling, where the MODEL publishes a number
/// precisely so that a proof need not photograph a window.
///
/// **The agent's `export` is a job here (spec §11 #326).** It keeps its
/// refusals synchronous, then enqueues exactly as Add to Queue does and
/// answers the job's id at once; `export_status` follows the job and
/// `cancel_export` calls `cancel` (`AgentServer+ExportStatus.swift`). The
/// queue's own API is unchanged by it: the mirror reads `job(_:)` and
/// observes `didChangeNotification` like the window does, and no tool
/// exists for a person's own queued job.
///
/// **One job at a time, on the MAIN thread, a fresh `Exporter` for each.**
/// `Exporter.export`'s own doc says main-thread-only and one export at a time,
/// and it means both: it schedules a run-loop `Timer` — which must be
/// invalidated on the thread it was scheduled on — and calls its progress and
/// completion handlers on the main thread. So this is a CHAIN and not a pool:
/// `start()` runs the head of the list and each completion runs the next. A
/// `DispatchQueue` of exporters would be the wrong shape whatever the machine's
/// core count, and not only because of the timer — an `Exporter` carries
/// per-export state (`recipeKey`, `cancelRequested`, the loudness scratch
/// buffer), which is why each job gets its own rather than one being reset
/// between jobs. Every method below is main-thread-only for that reason, like
/// the exporter it drives.
///
/// **What a job holds is the whole of what it will write, captured when it was
/// confirmed.** The `ReelProject` is a handle and handles are immutable (spec
/// §5.5) — every edit and every undo makes a NEW one — so a queued write cannot
/// be reached by an edit made after it, and it needs no clone: `Exporter.export`
/// publishes it on a `RecipeSource` key it mints for itself, never the
/// document's, so even the frames the compositor serves this export come from
/// this handle. The document may be edited, undone or CLOSED while the job
/// waits; the handle is retained here and the Rust project behind it lives
/// until the job is gone.
///
/// **And the media URLs are resolved at ENQUEUE, which is what makes them part
/// of that same snapshot.** `ProjectDocument.mediaURLs()` resolves a bookmark
/// and asks the filesystem whether the file is there (`mediaURL(for:)`), so it
/// is a reading of the disk at the moment it is called: resolving at RUN time
/// would silently pick up a Relink… or a moved file from after the job was
/// queued, which is the exact change an immutable job exists to exclude. That
/// rule is structural here rather than remembered — `enqueue` takes a
/// `[UInt32: URL]` and a job holds no document, so there is nothing to ask
/// again later even if somebody wanted to.
///
/// **The REVERSE resolution is the third thing in that snapshot, and it was
/// missing.** Handle immutability covers the project and nothing beside it:
/// which clips play from a pre-rendered backwards file is a reading of the
/// disk too (`ProjectDocument.reverseState`, `ReverseCache.existing`), it
/// cannot be derived from a bare handle, and it lives in a side table keyed by
/// object IDENTITY — which the document overwrites on every edit and removes
/// when it closes. So a job queued from a timeline holding a reversed clip
/// used to answer `.none` the moment anything was edited, and `.none` means
/// "not reversed": the export took the forward asset at the mirrored source
/// window, unslated and unreported. It is captured here at enqueue, exactly as
/// the URLs are, and PINNED to this job's own handle for the length of its
/// write (`ReverseSource.pin`). Anything else the picture depends on that is
/// neither in the handle nor derivable from it joins that list.
///
/// **A bundled-encoder job also waits for memory (spec §11 CX-18).** An AV1 or VP9 job
/// starts only while `ExportEncoderLedger` admits it: nothing else booked, or the running
/// encoder exports — an Export… sheet's beside this queue's — fitting with it in a quarter
/// of physical memory. A held job says why in its `message` and is PASSED OVER by a later
/// job the ledger admits, an AVFoundation job always; the chain stays one job at a time.
/// The running job is booked from just before its `export` call to its finish, and a
/// booking's end — the queue's own or a sheet's — re-runs `start()` through the ledger's
/// notification.
final class ExportQueueController {
    /// The app's one queue: the export sheet's Add to Queue fills it and
    /// Window ▸ Export Queue shows it.
    static let shared = ExportQueueController()

    /// Where a job is. A closed set with no associated values, so the two
    /// readers ask it different questions without either having to spell a
    /// message: the window's row draws its own wording (which carries a
    /// percentage the state cannot know), and a probe compares the case and
    /// reads `Job.message` for the sentence. The raw values are the same
    /// strings a probe writes into its JSON answer.
    enum State: String {
        /// Queued and not started. The only state a job can be enqueued in.
        case waiting
        /// The one job an `Exporter` is running. At most one at any moment.
        case running
        /// The file landed.
        case completed
        /// Stopped by a person, either before it started or mid-write — in
        /// which case its half-written file has been removed.
        case cancelled
        /// The exporter refused or failed. Whatever it had written is LEFT on
        /// disk, which is `ExportProgressSheetController`'s posture and not a
        /// new one: a cancel is a person saying "not this", where a failure is
        /// evidence, and the file names itself in the message.
        case failed

        /// Whether the job is over, however it ended — the test for "may be
        /// removed from the list" and for "no longer holds a project handle
        /// worth keeping".
        var isFinished: Bool { self == .completed || self == .cancelled || self == .failed }
    }

    /// One confirmed export. Everything it needs was read when it was
    /// enqueued; see the type doc for why that is the whole point of it.
    struct Job {
        /// Monotonic within one launch. The window's rows and every method
        /// below address a job by this rather than by index, because a job can
        /// be removed from the middle of the list while a later one runs.
        let id: UInt64
        /// The timeline as it was confirmed — immutable, and retained here, so
        /// the document behind it may be edited, undone or closed.
        ///
        /// A FINISHED job goes on holding it, and that is a real cost stated
        /// rather than hidden: a handle is the project's model and not its
        /// media, so it is JSON-sized, and Clear Finished (or Remove) is what
        /// releases it along with the row that says where the file went.
        /// Dropping the handle at the finish would buy those bytes back and
        /// cost the field its `let` — an immutable job whose contents change
        /// once is a harder thing to reason about than a list somebody tidies.
        let project: ReelProject
        /// The media files as they resolved AT ENQUEUE.
        let urls: [UInt32: URL]
        /// Which of this timeline's clips play from a pre-rendered backwards
        /// file, as that resolved AT ENQUEUE — the type doc's third piece of
        /// the snapshot. Read from `ReverseSource` here and published back to
        /// it under this job's own handle while the job runs, because the
        /// document's copy is overwritten by the next edit and dropped when it
        /// closes.
        let reverse: ReverseResolution
        let settings: ExportSettings
        let destination: URL
        /// What this export asks of the PICTURE besides the timeline — the
        /// burn-in (`RecipeOptions`). Carried per job, because two jobs from
        /// one document may legitimately differ in it.
        let options: RecipeOptions
        /// The document's compiled graphics as they stood AT ENQUEUE (G-13) —
        /// the type doc's list again: a module saved after Add to Queue is not
        /// in the handle, and the document's set is swapped by that save and
        /// dropped when it closes. `Exporter.export` pins it for the write.
        let graphics: GraphicSet?
        var state: State = .waiting
        /// 0…1, and only meaningful while `state` is `.running`.
        var progress: Double = 0
        /// The line a person reads when it is over: what was written and what
        /// the file measured, or why it stopped — plus the one thing worth
        /// saying mid-flight, that a cancel is in hand. While it waits, the
        /// ledger's sentence when the memory limit holds it (CX-18), else nil.
        var message: String?
        /// What the exporter says it is doing right now, or nil for "writing",
        /// which is the caller's own wording. Today the only phase is the
        /// loudness measurement, which on an audio-only export is half the wait
        /// and the half where nothing is on disk yet.
        ///
        /// A field of its own rather than a use of `message`, because the two
        /// are written by different things at the same time: the progress tick
        /// arrives ten times a second and would otherwise wipe the "Stopping…"
        /// a person had just asked for.
        var phase: String?
        /// Set on a COMPLETED job when a later job starts writing to the same
        /// path, because from that moment this row's file is not this row's
        /// any more — `Exporter.startWriting` removes whatever is at the
        /// destination before it builds its pipeline, so the earlier export is
        /// gone whether the later one succeeds, fails or is cancelled.
        ///
        /// The row stops claiming "Exported …" and stops offering Show in
        /// Finder. It is a fact about what happened rather than a state: the
        /// job really did complete, and rewriting its `state` would lose that.
        ///
        /// One case marks it where the file in fact survives, and it is the
        /// honest direction of the two: a later job whose COMPOSITION fails to
        /// build returns before the delete, so nothing was destroyed. It is
        /// left alone rather than reached for, because knowing which failures
        /// precede the delete means reading `Exporter`'s stages from here, and
        /// a shared destination implies a shared project — a build that failed
        /// for job 2 would almost always have failed for job 1.
        var superseded: Bool = false
        /// What the graphics warned while a COMPLETED job's file was drawn
        /// (G-24 (c)): the row's count and its tooltip's list.
        var graphicWarnings: [ExportGraphicWarning] = []
        /// What a COMPLETED job's sound measured, read off its exporter at the
        /// finish — the figures the row's message summarises, kept whole for
        /// `export_status`'s `loudness` (spec §11 #326). nil otherwise.
        var loudness: ExportLoudness? = nil

        /// What the row calls this job. The file name and not the path: the
        /// row is narrow, and the full path is the tooltip's job.
        var name: String { destination.lastPathComponent }
    }

    /// Posted after any change to `jobs` — an enqueue, a progress tick, a
    /// finish, a cancel, a removal — with the controller as the `object`, so
    /// an observer of the shared queue is never woken by a probe's own
    /// instance. Main thread, like everything else here.
    static let didChangeNotification = Notification.Name(
        "com.kgalligan.framejob.exportQueueDidChange")

    /// Every job this launch still knows about, in the order they were added.
    /// A finished one stays until it is removed, because "it is done and here
    /// is where it went" is the queue's other job.
    private(set) var jobs: [Job] = []

    /// The exporter running `runningID`'s job, and nil whenever nothing is
    /// running. Set and cleared together with the job's state, so `isIdle` can
    /// be answered from `jobs` alone.
    private var exporter: Exporter?

    /// The handle whose reverse resolution is pinned in `ReverseSource` right
    /// now — the running job's, and nil whenever nothing is running. Held
    /// separately from the job so that `launch` and `finished` are provably one
    /// pin and one release, whatever happens to the list in between.
    private var pinnedProject: ReelProject?

    /// The running job's booking in the encoder ledger (CX-18), nil whenever nothing runs
    /// or the running job is an AVFoundation one. Taken BEFORE `end` in `finished`: the
    /// ledger's post can launch — and book — the next job inside that call.
    private var ledgerToken: UInt64?

    private let ledger = ExportEncoderLedger.shared

    /// True only while `start()` is inside `Exporter.export`. An early refusal
    /// — `noPlan`, `emptyTimeline` — completes SYNCHRONOUSLY, so `finished`
    /// can run before `export` has returned; without this flag the next job
    /// would be launched from inside the previous one's stack frame and a
    /// queue of refusals would recurse as deep as it is long. With it, a
    /// re-entrant `start()` is refused and the frame already on the stack
    /// picks the next job up in its own loop.
    private var isLaunching = false

    private var nextID: UInt64 = 1

    /// Internal rather than private, and deliberately: a proof compiles a
    /// probe out of `app/Sources` and makes its OWN queue, so that running two
    /// jobs in a script cannot disturb — or be disturbed by — the app's shared
    /// one. It is the same reason `ExportPresetsStore` is a value a test can
    /// make.
    init() {
        // A booking's end — a sheet's as much as this queue's — may admit a held job.
        NotificationCenter.default.addObserver(
            self, selector: #selector(ledgerChanged(_:)),
            name: ExportEncoderLedger.didChangeNotification, object: ledger)
    }

    @objc private func ledgerChanged(_ note: Notification) { start() }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ExportQueueController does not support NSCoder")
    }

    // MARK: - Asking

    /// Nothing waiting and nothing running. The queue's own "are we there
    /// yet", and what a probe spins the run loop until.
    ///
    /// Answered from `jobs` rather than from `exporter`, so it means the same
    /// thing to a caller that cannot see the private state.
    var isIdle: Bool {
        !jobs.contains { $0.state == .waiting || $0.state == .running }
    }

    /// The job an exporter is writing right now, if any.
    var runningJob: Job? { jobs.first { $0.state == .running } }

    /// How many are still queued behind it.
    var waitingCount: Int { jobs.filter { $0.state == .waiting }.count }

    func job(_ id: UInt64) -> Job? { jobs.first { $0.id == id } }

    // MARK: - Filling

    /// Adds one confirmed export and starts the queue if it is not already
    /// running. Answers the job's id, so a caller can follow it.
    ///
    /// The arguments are `Exporter.export`'s, and that is not a coincidence:
    /// a job is exactly the call that will be made, held until its turn. Both
    /// `project` and `urls` are read by the CALLER, at the moment the save
    /// panel answered (`EditorViewController.enqueueExport`), which is what
    /// the type doc means by capturing at enqueue.
    ///
    /// **Two jobs may name one file, and the queue still does not refuse it —
    /// but it no longer pretends the person was warned.** The reason first
    /// given here was that "the save panel asked about replacing an existing
    /// file both times", and that is false in exactly the case that matters:
    /// `NSSavePanel` prompts only when something is at the path as Save is
    /// confirmed, and job 1 spends its build and its whole loudness
    /// measurement pass with nothing at the destination — `Exporter.export`
    /// does both before `startWriting` deletes and `AVAssetWriter` creates —
    /// so two Add to Queue actions in quick succession are never asked
    /// anything. Refusing here would still be wrong: overwriting your own
    /// export is a thing a person is allowed to do, and the queue must not be
    /// the one place in the app where they may not. What was wrong was the
    /// silence AFTERWARDS, and `launch` is where that is answered — the
    /// earlier row is marked `superseded` the moment a later job starts
    /// writing to its path, so no row goes on offering a file that another
    /// job has since deleted or replaced.
    @discardableResult
    func enqueue(
        project: ReelProject, urls: [UInt32: URL], settings: ExportSettings, to url: URL,
        options: RecipeOptions = .none, graphics: GraphicSet? = nil
    ) -> UInt64 {
        let id = nextID
        nextID += 1
        jobs.append(
            Job(
                id: id, project: project, urls: urls,
                // The third piece of the enqueue-time snapshot; the type doc
                // says why it cannot be left to be asked again at run time.
                reverse: ReverseSource.shared.resolution(publishedFor: project),
                settings: settings, destination: url, options: options, graphics: graphics))
        didChange()
        start()
        return id
    }

    // MARK: - Running

    /// Runs the first waiting job the encoder ledger admits, if nothing is
    /// running already — passing over a held one (CX-18 (7)). Idempotent
    /// and safe to call at any time: `enqueue` calls it, every completion
    /// calls it, the ledger's change calls it, and a caller may call it itself.
    ///
    /// The loop is for the synchronous-refusal case `isLaunching` describes: a
    /// job the exporter refuses without ever going asynchronous has already
    /// finished by the time `launch` returns, and this frame takes the next
    /// one rather than recursing into it.
    func start() {
        guard !isLaunching else { return }
        isLaunching = true
        defer { isLaunching = false }
        while exporter == nil, let index = jobs.firstIndex(where: {
            $0.state == .waiting && ledger.admits($0.settings)
        }) {
            launch(at: index)
        }
        noteHeld()
    }

    /// Every waiting encoder job's `message` set to why it is held, or cleared when it is
    /// not — leaving out this queue's own running booking, which it waits behind anyway.
    private func noteHeld() {
        var changed = false
        for index in jobs.indices
        where jobs[index].state == .waiting && jobs[index].settings.writer != nil {
            let sentence = ledger.waitingSentence(for: jobs[index].settings, ignoring: ledgerToken)
            if jobs[index].message != sentence {
                jobs[index].message = sentence
                changed = true
            }
        }
        if changed { didChange() }
    }

    /// One job handed to one fresh `Exporter`. The exporter is stored BEFORE
    /// the call, because an early refusal calls back before `export` returns
    /// and `finished` has to find it there.
    private func launch(at index: Int) {
        let job = jobs[index]
        jobs[index].state = .running
        jobs[index].progress = 0
        jobs[index].message = nil
        jobs[index].phase = nil
        // Any COMPLETED row naming this same path stops claiming its file
        // here, and here rather than when the file is actually deleted: the
        // delete happens inside `Exporter.startWriting`, seconds later and in
        // a file this one may not reach into, and being early is the honest
        // direction — a row that stops offering a file just before it is
        // destroyed costs a person nothing, where one that offers it just
        // after sends them to the Finder for something that is gone.
        for other in jobs.indices
        where other != index && jobs[other].state == .completed
            && jobs[other].destination == job.destination
        {
            jobs[other].superseded = true
        }
        // The job's own reverse resolution, held against its own handle for
        // exactly the length of this write. At most one pin exists at a time,
        // which is the invariant `ReverseSource.pin` asks its callers for and
        // which this class keeps for free by running one job at a time.
        ReverseSource.shared.pin(job.reverse, for: job.project)
        pinnedProject = job.project
        // Booked BEFORE `export`, whose early refusals finish synchronously inside it.
        ledgerToken = ledger.begin(job.settings)
        let exporter = Exporter()
        self.exporter = exporter
        didChange()
        exporter.export(
            project: job.project, urls: job.urls, settings: job.settings, to: job.destination,
            options: job.options, graphics: job.graphics,
            progress: { [weak self] value in self?.progressed(job.id, value) },
            completion: { [weak self] result in self?.finished(job.id, result) })
    }

    private func progressed(_ id: UInt64, _ value: Double) {
        guard let index = jobs.firstIndex(where: { $0.id == id }),
            jobs[index].state == .running
        else { return }
        jobs[index].progress = min(max(value, 0), 1)
        // The exporter names its own phase while it has one. The progress
        // sheet asks the same question with the same call; a row that said
        // "Writing" through the measurement would be claiming a file that does
        // not exist yet.
        jobs[index].phase = exporter?.phaseDescription
        didChange()
    }

    /// The one exit for all three outcomes, and the mirror of
    /// `ExportProgressSheetController.finished` — deliberately, because there
    /// must not be two accounts of what finishing an export means. The
    /// exporter is cleared first, so the `start()` at the foot can hand the
    /// next job a fresh one.
    private func finished(_ id: UInt64, _ result: Result<URL, any Error>) {
        // Read BEFORE the exporter is dropped: `Exporter.finish` publishes the
        // measurement and then calls this, so the report is there now and only
        // now.
        let report = exporter?.loudnessReport
        let measured = report.map { " \($0.summary)." } ?? ""
        let warnings = exporter?.graphicWarnings ?? []
        exporter = nil
        // The pin goes with the exporter, and from `pinnedProject` rather than
        // from the job, so that releasing it cannot depend on the job still
        // being in the list. Exactly one release per `launch`, which is what
        // `ReverseSource.pin` asks for; a pin left behind would retain the
        // Rust project for the life of the process.
        if let pinned = pinnedProject {
            ReverseSource.shared.unpin(pinned)
            pinnedProject = nil
        }
        if let index = jobs.firstIndex(where: { $0.id == id }) {
            jobs[index].phase = nil
            switch result {
            case .success(let url):
                jobs[index].state = .completed
                jobs[index].progress = 1
                jobs[index].graphicWarnings = warnings
                jobs[index].loudness = report
                // The count BEFORE the loudness figures: the row truncates
                // its tail (`ExportQueueRowView`).
                jobs[index].message = "Exported “\(url.lastPathComponent)”."
                    + Exporter.graphicWarningSuffix(warnings, hover: false) + measured
            case .failure(let error):
                if case Exporter.ExportError.cancelled = error {
                    // A cancelled job leaves nothing behind, and this line is
                    // DEFENCE IN DEPTH rather than the thing that achieves it
                    // — measured, because the obvious reading is wrong and a
                    // reader who believes it would be relying on a guarantee
                    // this line does not provide. Both pipelines already
                    // clean up after themselves: `AVAssetWriter.cancelWriting()`
                    // removes its own part-file (`ExporterWriter.swift` says
                    // so where it calls it) and `ImageSequenceWriter.report`
                    // removes its own. Deleting this line changes no observable
                    // outcome — phase 7's proof mutated it away and scored
                    // 77/77 — so the check beside it is written as the OUTCOME
                    // ("nothing is left behind") and not as a guard on this
                    // call. Keep it: it costs nothing, it states the policy
                    // where the policy is decided, and it is what holds if a
                    // third pipeline ever arrives that is less tidy.
                    // `ExportProgressSheetController.finished` is the same line
                    // for the same reason.
                    try? FileManager.default.removeItem(at: jobs[index].destination)
                    jobs[index].state = .cancelled
                    jobs[index].progress = 0
                    jobs[index].message = "Cancelled."
                } else {
                    jobs[index].state = .failed
                    jobs[index].progress = 0
                    jobs[index].message = error.localizedDescription
                }
            }
        }
        didChange()
        // Cleared before `end`, whose post may launch and book the next job.
        let token = ledgerToken
        ledgerToken = nil
        ledger.end(token)
        start()
    }

    // MARK: - Stopping and tidying

    /// Stops one job, whether it has started or not.
    ///
    /// A WAITING job is simply marked: it has no exporter to stop and no file
    /// to remove, because nothing has been written under its name. A RUNNING
    /// one is asked to stop and answers through `finished`, which is where its
    /// file is removed — one exit, so a cancel from the window and a cancel
    /// from a script clean up identically. A finished job is left alone.
    func cancel(_ id: UInt64) {
        guard let index = jobs.firstIndex(where: { $0.id == id }) else { return }
        switch jobs[index].state {
        case .waiting:
            jobs[index].state = .cancelled
            jobs[index].message = "Cancelled before it started."
            didChange()
        case .running:
            jobs[index].message = "Stopping…"
            exporter?.cancel()
            didChange()
        case .completed, .cancelled, .failed:
            break
        }
    }

    /// Stops everything. The WAITING jobs go first and the running one last,
    /// and the order is load-bearing: cancelling the running job posts its
    /// completion, and a completion starts the next waiting job — so stopping
    /// the writer first would start the very jobs this is meant to stop.
    func cancelAll() {
        for job in jobs where job.state == .waiting { cancel(job.id) }
        if let running = runningJob { cancel(running.id) }
    }

    /// Drops one finished row. A job still waiting or running is not removed —
    /// cancel it first, which is what the window's one button does in its two
    /// states.
    func remove(_ id: UInt64) {
        guard let index = jobs.firstIndex(where: { $0.id == id }),
            jobs[index].state.isFinished
        else { return }
        jobs.remove(at: index)
        didChange()
    }

    /// Drops every finished row and leaves the queue itself running.
    func clearFinished() {
        let before = jobs.count
        jobs.removeAll { $0.state.isFinished }
        if jobs.count != before { didChange() }
    }

    private func didChange() {
        NotificationCenter.default.post(name: Self.didChangeNotification, object: self)
    }
}

// Codec export C6a (spec §11 CX-18) — the Export Queue's memory limit on bundled-encoder
// jobs and the sheet's time estimate, in process. `encoder_limit_proof.py` builds it as
// `main.swift` over every file in `app/Sources` but the app's own `main.swift`, on
// `swift_build.py`'s line, beside `Blank.mp4`, `Fonts` and a `default.metallib` of
// `Compositor.metal` and `ExportI010.metal`, and runs it:
//
//   encoder_limit_probe <AV.mov> <out folder> <answer.json>
//
// No app and no instance: the two live projects are built here from AV.mov, as
// `webm_readers_probe.swift` builds A1's — A1 (640 × 360, 30 fps, AV.mov from 0 under a
// two-second text clip) and W9 (1920 × 1080, AV.mov 24 times end to end at scale 3).
//
// The answer is RAW: the tables (P0), what the rule and the estimate answered (R, E), and
// what the live queue did (Q), each event stamped with a sequence number. The proof
// computes every expected value from P0's tables in its own arithmetic and scores the rows.
import AVFoundation
import AppKit
import Foundation

DecoderSupport.enable()
NSApplication.shared.setActivationPolicy(.prohibited)

let arguments = CommandLine.arguments
guard arguments.count == 4 else {
    print("usage: encoder_limit_probe <AV.mov> <out folder> <answer.json>")
    exit(2)
}
let media = URL(fileURLWithPath: arguments[1])
let outFolder = URL(fileURLWithPath: arguments[2], isDirectory: true)
let answerURL = URL(fileURLWithPath: arguments[3])
try? FileManager.default.createDirectory(at: outFolder, withIntermediateDirectories: true)

let binaryDirectory = URL(fileURLWithPath: arguments[0]).deletingLastPathComponent()
    .standardizedFileURL
let fontsDirectory = binaryDirectory.appendingPathComponent("Fonts")
for name in (try? FileManager.default.contentsOfDirectory(atPath: fontsDirectory.path)) ?? []
where name.hasSuffix(".ttf") || name.hasSuffix(".otf") {
    CTFontManagerRegisterFontsForURL(
        fontsDirectory.appendingPathComponent(name) as CFURL, .process, nil)
}

var answer: [String: Any] = [:]
func finish() -> Never {
    let data = (try? JSONSerialization.data(withJSONObject: answer, options: [.sortedKeys]))
        ?? Data("{}".utf8)
    try? data.write(to: answerURL)
    exit(0)
}

struct ProbeError: Error, CustomStringConvertible {
    let description: String
    init(_ d: String) { description = d }
}

// MARK: - P0: the tables

func keyJSON(_ key: ExportEncoderKey) -> [String: Any] {
    ["preset": key.preset, "speed": key.speed?.rawValue ?? NSNull(), "bits": key.bits]
}
func figureJSON(_ f: ExportEncoderFigure) -> [String: Any] {
    ["at1080": f.at1080, "at2160": f.at2160, "source": f.source]
}
answer["pixels1080"] = ExportEncoderCosts.pixels1080
answer["pixels2160"] = ExportEncoderCosts.pixels2160
answer["memory"] = ExportEncoderCosts.memory.map { key, figure in
    ["key": keyJSON(key), "figure": figureJSON(figure)]
}
answer["time"] = ExportEncoderCosts.time.map { key, entry in
    ["key": keyJSON(key), "perFrame": figureJSON(entry.perFrame),
     "setupSeconds": entry.setupSeconds]
}

// MARK: - Synthetic settings

/// Settings as the core would answer them for a row, decoded through the app's own type.
func settings(
    preset: String, writer: String?, speed: EncoderSpeed? = nil, color: String? = nil,
    width: Int, height: Int, frames: Int = 300, fps: [Int] = [30, 1]
) -> ExportSettings {
    var object: [String: Any] = [
        "preset": preset, "container": "mp4", "codec": preset, "width": width,
        "height": height, "fps": fps,
        "range": ["start": 0, "duration": frames * Int(Fps.thirty.frameDuration)],
    ]
    if let writer { object["writer"] = writer }
    if let speed { object["encoder_speed"] = speed.rawValue }
    if let color { object["color"] = color }
    let data = try! JSONSerialization.data(withJSONObject: object)
    return ReelJSON.decode(ExportSettings.self, from: String(decoding: data, as: UTF8.self))!
}

/// One settings per measured key, by the proof's name for it.
func keyed(width: Int, height: Int, frames: Int = 300) -> [(String, ExportSettings)] {
    var out: [(String, ExportSettings)] = []
    for preset in ["av1", "av1_webm"] {
        for speed in EncoderSpeed.allCases {
            out.append(("\(preset):\(speed.rawValue)", settings(
                preset: preset, writer: "svt_av1", speed: speed, width: width, height: height,
                frames: frames)))
        }
    }
    out.append(("vp9_webm:sdr", settings(
        preset: "vp9_webm", writer: "libvpx", width: width, height: height, frames: frames)))
    out.append(("vp9_webm:hlg", settings(
        preset: "vp9_webm", writer: "libvpx", color: "hlg", width: width, height: height,
        frames: frames)))
    out.append(("vp9_alpha_webm", settings(
        preset: "vp9_alpha_webm", writer: "libvpx", width: width, height: height,
        frames: frames)))
    return out
}

// MARK: - R: the rule

let gib: UInt64 = 1 << 30
var r1: [[String: Any]] = []
for physical in [16, 24, 32, 48, 64, 96, 128] {
    let ledger = ExportEncoderLedger(physicalMemory: UInt64(physical) * gib)
    for (width, height) in [(1920, 1080), (3840, 2160)] {
        for (name, s) in keyed(width: width, height: height) {
            let fresh = ExportEncoderLedger(physicalMemory: UInt64(physical) * gib)
            var admitted = 0
            while fresh.admits(s), admitted < 1000 {
                _ = fresh.begin(s)
                admitted += 1
            }
            r1.append([
                "physicalGiB": physical, "budget": ledger.budget, "key": name,
                "width": width, "height": height,
                "cost": ExportEncoderCosts.memoryBytes(for: s, budget: ledger.budget),
                "admitted": admitted,
            ])
        }
    }
}
answer["r1"] = r1

do {
    let ledger = ExportEncoderLedger(physicalMemory: 64 * gib)
    // A writer row with no entry: every real row is measured (codec-export C5's fix pass
    // measured vp9_alpha_webm), so the rule is read on a synthetic one.
    let alpha = settings(preset: "unmeasured_webm", writer: "libvpx", width: 1920, height: 1080)
    let av1 = settings(preset: "av1", writer: "svt_av1", speed: .faster, width: 640, height: 360)
    let firstAlpha = ledger.admits(alpha)
    let alphaToken = ledger.begin(alpha)
    let secondAlpha = ledger.admits(alpha)
    let av1Beside = ledger.admits(av1)
    let alphaCost = ExportEncoderCosts.memoryBytes(for: alpha, budget: ledger.budget)
    ledger.end(alphaToken)
    let av1Token = ledger.begin(av1)
    let alphaBesideAV1 = ledger.admits(alpha)
    ledger.end(av1Token)
    answer["r2"] = [
        "budget": ledger.budget, "alphaCost": alphaCost, "firstAdmitted": firstAlpha,
        "secondAdmitted": secondAlpha, "av1BesideAlpha": av1Beside,
        "alphaBesideAV1": alphaBesideAV1, "idle": ledger.runningCosts.isEmpty,
    ]

    let h264 = settings(preset: "h264", writer: nil, width: 3840, height: 2160)
    let full = ExportEncoderLedger(physicalMemory: 16 * gib)
    let held = full.begin(alpha)
    let before = full.runningCosts
    let h264Token = full.begin(h264)
    answer["r3"] = [
        "token": h264Token.map { NSNumber(value: $0) } ?? NSNull(),
        "admittedBesideFull": full.admits(h264),
        "costsUnchanged": full.runningCosts == before,
        "cost": ExportEncoderCosts.memoryBytes(for: h264, budget: full.budget),
        "key": ExportEncoderKey(settings: h264) == nil,
    ]
    full.end(held)
}

// MARK: - E: the estimate

var e1: [[String: Any]] = []
for (width, height) in [(1280, 720), (1920, 1080), (2560, 1440), (3840, 2160), (7680, 4320)] {
    for frames in [150, 300, 1800] {
        for (name, s) in keyed(width: width, height: height, frames: frames) {
            e1.append([
                "key": name, "width": width, "height": height, "frames": frames,
                "seconds": ExportEncoderCosts.estimatedSeconds(for: s) ?? NSNull(),
                "line": ExportEncoderCosts.sheetLine(for: s) ?? NSNull(),
            ])
        }
    }
}
answer["e1"] = e1
answer["e2"] = [0.4, 2.4, 7.4, 57.4, 59.9, 60, 89, 90, 3569, 3570, 3600, 5399, 5400].map {
    ["seconds": $0, "text": ExportEncoderCosts.estimateText(seconds: $0)]
}
let h264Settings = settings(preset: "h264", writer: nil, width: 1920, height: 1080)
// A measured key at a rate that cannot be stepped: no frame count, so no estimate.
let unsteppedSettings = settings(
    preset: "av1", writer: "svt_av1", speed: .balanced, width: 1920, height: 1080,
    fps: [0, 1])
answer["e3"] = [
    "line": ExportEncoderCosts.sheetLine(for: h264Settings).map { $0 as Any } ?? NSNull(),
    "seconds": ExportEncoderCosts.estimatedSeconds(for: h264Settings).map { $0 as Any }
        ?? NSNull(),
    "unsteppedFrames": unsteppedSettings.sequenceFrameCount.map { $0 as Any } ?? NSNull(),
    "unsteppedLine": ExportEncoderCosts.sheetLine(for: unsteppedSettings).map { $0 as Any }
        ?? NSNull(),
    "unsteppedSeconds": ExportEncoderCosts.estimatedSeconds(for: unsteppedSettings)
        .map { $0 as Any } ?? NSNull(),
] as [String: Any]

// MARK: - The live projects

func apply(_ project: ReelProject, _ op: ReelOp) throws -> ReelProject {
    switch try project.applying([op]) {
    case .applied(let next): return next
    case .identity: return project
    case .refused(let refusal): throw ProbeError("\(op.name) was refused: \(refusal.reason)")
    }
}

/// The project with AV.mov in its media, on a canvas of `width` × `height` at 30 fps.
func withMedia(width: Int, height: Int) throws -> (ReelProject, UInt32) {
    var project = try apply(
        ProjectDocument().project, .setCanvas(width: width, height: height, fps: Fps.thirty))
    let asset = AVURLAsset(url: media)
    let video = asset.tracks(withMediaType: .video).first
    let size = video?.naturalSize ?? .zero
    let id = project.snapshot.nextId
    project = try apply(project, .addMedia(descriptor: MediaDescriptor(
        path: media.path, kind: .video, duration: CompositionBuilder.ticks(asset.duration),
        width: Int(size.width), height: Int(size.height), fps: Fps.thirty,
        hasVideo: video != nil, hasAudio: !asset.tracks(withMediaType: .audio).isEmpty)))
    return (project, id)
}

func a1() throws -> ReelProject {
    var (project, id) = try withMedia(width: 640, height: 360)
    guard let track = project.snapshot.tracks.first?.id else { throw ProbeError("no track") }
    project = try apply(project, .addClip(track: track, media: id, at: 0))
    project = try apply(project, .addTrack(index: project.snapshot.tracks.count, name: "Titles"))
    guard let titles = project.snapshot.tracks.last?.id else { throw ProbeError("no titles") }
    return try apply(project, .addTextClip(
        track: titles, at: 0, duration: 2 * ReelTime.perSecond, text: TextPatch(content: "AV1")))
}

func w9() throws -> ReelProject {
    var (project, id) = try withMedia(width: 1920, height: 1080)
    guard let track = project.snapshot.tracks.first?.id else { throw ProbeError("no track") }
    for k in 0..<24 {
        project = try apply(project, .addClip(
            track: track, media: id, at: Ticks(k) * 5 * ReelTime.perSecond))
    }
    let clips = project.snapshot.clips.map(\.id)
    return try apply(project, .setVideo(clips: clips, patch: VideoPatch(scale: 3.0)))
}

func urls(_ project: ReelProject) -> [UInt32: URL] {
    var out: [UInt32: URL] = [:]
    for item in project.snapshot.media { out[item.id] = URL(fileURLWithPath: item.path) }
    return out
}

func export(
    _ project: ReelProject, _ preset: String, speed: EncoderSpeed? = nil
) throws -> ExportSettings {
    var overrides: [String: Any] = [:]
    if let speed { overrides["encoder_speed"] = speed.rawValue }
    return try ReelExport.settings(
        project, preset: preset, overrides: overrides.isEmpty ? nil : overrides)
}

func describe(_ s: ExportSettings) -> [String: Any] {
    ["preset": s.preset, "writer": s.writer ?? NSNull(), "speed": s.encoderSpeed?.rawValue
        ?? NSNull(), "color": s.color ?? NSNull(), "width": s.width, "height": s.height,
     "frames": s.sequenceFrameCount ?? 0]
}

/// A private stored property, by reflection.
func reflected<T>(_ object: Any, _ name: String, as: T.Type) -> T? {
    Mirror(reflecting: object).children.first { $0.label == name }?.value as? T
}

func spin(until done: () -> Bool, timeout: Double) -> Bool {
    let deadline = Date().addingTimeInterval(timeout)
    while !done(), Date() < deadline {
        RunLoop.main.run(mode: .default, before: Date().addingTimeInterval(0.02))
    }
    return done()
}

func out(_ name: String) -> URL {
    let url = outFolder.appendingPathComponent(name)
    try? FileManager.default.removeItem(at: url)
    return url
}

func headlessSheet(
    _ project: ReelProject, _ settings: ExportSettings, to url: URL
) -> ExportProgressSheetController {
    let sheet = ExportProgressSheetController(
        project: project, urls: urls(project), settings: settings, to: url)
    _ = sheet.view
    sheet.viewDidAppear()
    return sheet
}

func sheetFinished(_ sheet: ExportProgressSheetController) -> Bool {
    reflected(sheet, "didFinish", as: Bool.self) == true
}

/// What the shared queue and ledger did during a live row: every job's state at each
/// change, stamped by a sequence number, and the sequence at which the sheet was first
/// seen finished (checked at every change and every spin, before the jobs are read).
final class Watch {
    let queue = ExportQueueController.shared
    var seq = 0
    var sheet: ExportProgressSheetController?
    var sheetFinishedAt: Int?
    var firstSeen: [String: Int] = [:]   // "<id>:<state>" → seq
    var ledgerCosts: [[UInt64]] = []
    var observers: [NSObjectProtocol] = []

    init() {
        observers.append(NotificationCenter.default.addObserver(
            forName: ExportQueueController.didChangeNotification, object: queue, queue: nil
        ) { [unowned self] _ in self.tick() })
        observers.append(NotificationCenter.default.addObserver(
            forName: ExportEncoderLedger.didChangeNotification,
            object: ExportEncoderLedger.shared, queue: nil
        ) { [unowned self] _ in
            self.ledgerCosts.append(ExportEncoderLedger.shared.runningCosts)
            self.tick()
        })
    }

    func tick() {
        seq += 1
        if sheetFinishedAt == nil, let sheet, sheetFinished(sheet) { sheetFinishedAt = seq }
        for job in queue.jobs {
            let key = "\(job.id):\(job.state.rawValue)"
            if firstSeen[key] == nil { firstSeen[key] = seq }
        }
    }

    func at(_ id: UInt64, _ state: ExportQueueController.State) -> Any {
        firstSeen["\(id):\(state.rawValue)"].map { $0 as Any } ?? NSNull()
    }

    func job(_ id: UInt64) -> [String: Any] {
        let job = queue.job(id)
        return [
            "state": job?.state.rawValue ?? "missing", "message": job?.message ?? NSNull(),
            "waiting": at(id, .waiting), "running": at(id, .running),
            "completed": at(id, .completed), "failed": at(id, .failed),
        ]
    }

    func stop() { observers.forEach(NotificationCenter.default.removeObserver) }
}

// MARK: - Q: the live queue

let ledger = ExportEncoderLedger.shared
let realPhysical = ledger.physicalMemory
var q: [String: Any] = [:]
do {
    let small = try a1()
    let long = try w9()
    let sheetSettings = try export(long, "av1", speed: .smaller)
    let aSettings = try export(small, "av1")
    let hSettings = try export(small, "h264")
    q["sheetSettings"] = describe(sheetSettings)
    q["aSettings"] = describe(aSettings)

    // Q1, Q2, Q4: the budget equal to the sheet job's own cost.
    let sheetCost = ExportEncoderCosts.memoryBytes(for: sheetSettings, budget: 0)
    ledger.physicalMemory = 4 * sheetCost
    q["q1Physical"] = ledger.physicalMemory
    let watch = Watch()
    let sheet = headlessSheet(long, sheetSettings, to: out("q1-sheet.mp4"))
    watch.sheet = sheet
    q["q1Booked"] = ledger.runningCosts
    let queue = ExportQueueController.shared
    let aURL = out("q1-a.mp4"), bURL = out("q1-b.mp4"), cURL = out("q1-c.mp4")
    let a = queue.enqueue(project: small, urls: urls(small), settings: aSettings, to: aURL)
    let b = queue.enqueue(project: small, urls: urls(small), settings: hSettings, to: bURL)
    let c = queue.enqueue(project: small, urls: urls(small), settings: hSettings, to: cURL)
    // Q2 and Q4, read at once: B is running and A held behind the sheet.
    q["q4BRunning"] = queue.job(b)?.state == .running
    q["q4A"] = queue.job(a).map { ExportQueueRowView.status($0) } ?? NSNull()
    q["q4C"] = queue.job(c).map { ExportQueueRowView.status($0) } ?? NSNull()
    q["q4ATip"] = queue.job(a).map { ExportQueueRowView.toolTip(for: $0) } ?? NSNull()
    q["q4CTip"] = queue.job(c).map { ExportQueueRowView.toolTip(for: $0) } ?? NSNull()
    AgentExports.shared.track(
        a, settings: aSettings, burnInTimecode: false,
        started: ProcessInfo.processInfo.systemUptime)
    q["q2"] = AgentExports.shared.status(a) ?? NSNull()
    q["q1HeldMessage"] = queue.job(a)?.message ?? NSNull()
    let sheetDone = spin(until: { sheetFinished(sheet) }, timeout: 600)
    watch.tick()
    let drained = spin(until: { queue.isIdle }, timeout: 120)
    watch.tick()
    q["q1"] = [
        "sheetDone": sheetDone, "drained": drained, "sheetFinishedAt": watch.sheetFinishedAt
            .map { $0 as Any } ?? NSNull(),
        "a": watch.job(a), "b": watch.job(b), "c": watch.job(c),
        "files": [aURL, bURL, cURL].map { FileManager.default.fileExists(atPath: $0.path) },
        "sheetStatus": reflected(sheet, "statusLabel", as: NSTextField.self)?.stringValue
            ?? "",
    ]
    q["q5Drained"] = ledger.runningCosts
    watch.stop()

    // Q3: a Mac so large nothing waits.
    ledger.physicalMemory = 1 << 40
    let watch3 = Watch()
    let fast = try export(long, "av1", speed: .faster)
    let sheet3 = headlessSheet(long, fast, to: out("q3-sheet.mp4"))
    watch3.sheet = sheet3
    let a3URL = out("q3-a.mp4")
    let a3 = queue.enqueue(project: small, urls: urls(small), settings: aSettings, to: a3URL)
    let sheet3Done = spin(until: { sheetFinished(sheet3) }, timeout: 600)
    watch3.tick()
    let drained3 = spin(until: { queue.isIdle }, timeout: 120)
    q["q3"] = [
        "sheetDone": sheet3Done, "drained": drained3,
        "sheetFinishedAt": watch3.sheetFinishedAt.map { $0 as Any } ?? NSNull(),
        "a": watch3.job(a3), "file": FileManager.default.fileExists(atPath: a3URL.path),
    ]
    watch3.stop()
    q["q5AfterQ3"] = ledger.runningCosts

    // Q5: two encoder jobs back to back — the second launches inside the first's `end`.
    let x = queue.enqueue(project: small, urls: urls(small), settings: aSettings,
                          to: out("q5-x.mp4"))
    let y = queue.enqueue(project: small, urls: urls(small), settings: aSettings,
                          to: out("q5-y.mp4"))
    let drained5 = spin(until: { queue.isIdle }, timeout: 300)
    q["q5BackToBack"] = [
        "drained": drained5, "x": queue.job(x)?.state.rawValue ?? "missing",
        "y": queue.job(y)?.state.rawValue ?? "missing", "costs": ledger.runningCosts,
    ]

    // Q5: synchronous refusals, in the queue and in a sheet.
    guard let empty = ReelProject.new(width: 640, height: 360, fps: Fps.thirty) else {
        throw ProbeError("no empty project")
    }
    // A1's own `av1` settings (the core resolves none for an empty range) over the empty
    // handle: `Exporter.export` refuses it synchronously, `emptyTimeline`.
    let emptySettings = aSettings
    let z = queue.enqueue(project: empty, urls: [:], settings: emptySettings,
                          to: out("q5-z.mp4"))
    q["q5QueueRefusal"] = [
        "state": queue.job(z)?.state.rawValue ?? "missing",
        "message": queue.job(z)?.message ?? NSNull(), "costs": ledger.runningCosts,
    ]
    let refused = headlessSheet(empty, emptySettings, to: out("q5-sheet.mp4"))
    q["q5SheetRefusal"] = [
        "finished": sheetFinished(refused), "costs": ledger.runningCosts,
        "status": reflected(refused, "statusLabel", as: NSTextField.self)?.stringValue ?? "",
    ]
} catch {
    q["error"] = "\(error)"
}
ledger.physicalMemory = realPhysical
answer["q"] = q
finish()

